use std::collections::HashSet;

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    // To minimize work, build the hash set on the smaller array
    if a.len() < b.len() {
        let set_a: HashSet<i32> = a.iter().cloned().collect();
        for &item in b.iter() {
            if set_a.contains(&item) {
                return true;
            }
        }
    } else {
        let set_b: HashSet<i32> = b.iter().cloned().collect();
        for &item in a.iter() {
            if set_b.contains(&item) {
                return true;
            }
        }
    }
    false
}

